namespace pto {
template <typename TileDst, typename TileSrc0, typename TileSrc1>
void TSub_Impl(TileDst& dst, TileSrc0& src0, TileSrc1& src1, unsigned validRow, unsigned validCol)
{
    cpu::parallel_for_rows(validRow, validCol, [&](std::size_t r) {
        PTO_CPU_VECTORIZE_LOOP
        for (std::size_t c = 0; c < validCol; ++c) {
            dst.SetElement(r, c, src0.GetElement(r, c) - src1.GetElement(r, c));
        }
    });
}

template <typename TileDst, typename TileSrc0, typename TileSrc1>
PTO_INTERNAL void TSUB_IMPL(TileDst& dst, TileSrc0& src0, TileSrc1& src1)
{
    static_assert(
        std::is_same_v<typename TileDst::DType, typename TileSrc0::DType> &&
            std::is_same_v<typename TileDst::DType, typename TileSrc1::DType>,
        "TSUB input and output dtypes must match.");
    unsigned row = dst.GetValidRow();
    unsigned col = dst.GetValidCol();
    PTO_ASSERT(
        src0.GetValidRow() == row && src0.GetValidCol() == col,
        "Fix: TSUB input tile src0 valid shape mismatch with output tile dst shape.");
    PTO_ASSERT(
        src1.GetValidRow() == row && src1.GetValidCol() == col,
        "Fix: TSUB input tile src1 valid shape mismatch with output tile dst shape.");
    TSub_Impl(dst, src0, src1, row, col);
}
} // namespace pto
#endif

