28	        uint8_t src0RepeatStride, uint8_t src1RepeatStride)
29	    {
30	        vadd(dst, src0, src1, repeats, 1, 1, 1, dstRepeatStride, src0RepeatStride, src1RepeatStride);
31	    }
32	};
33	
34	template <
35	    typename TileDataDst, typename TileDataSrc0, typename TileDataSrc1, unsigned elementsPerRepeat,
36	    unsigned blockSizeElem, unsigned dstRowStride, unsigned src0RowStride = dstRowStride,
37	    unsigned src1RowStride = dstRowStride>
38	__tf__ PTO_INTERNAL void TAdd(
39	    typename TileDataDst::TileDType __out__ dst, typename TileDataSrc0::TileDType __in__ src0,
40	    typename TileDataSrc1::TileDType __in__ src1, unsigned validRows, unsigned validCols)
41	{
42	    using T = typename TileDataDst::DType;
43	    __ubuf__ T* dstPtr = (__ubuf__ T*)__cce_get_tile_ptr(dst);
44	    __ubuf__ T* src0Ptr = (__ubuf__ T*)__cce_get_tile_ptr(src0);
45	    __ubuf__ T* src1Ptr = (__ubuf__ T*)__cce_get_tile_ptr(src1);
46	    if constexpr (dstRowStride == src0RowStride && dstRowStride == src1RowStride) {
47	        BinaryInstr<AddOp<T>, T, TileDataDst, elementsPerRepeat, blockSizeElem, dstRowStride>(
48	            dstPtr, src0Ptr, src1Ptr, validRows, validCols);
49	    } else {
50	        BinaryInstr<AddOp<T>, T, elementsPerRepeat, blockSizeElem, dstRowStride, src0RowStride, src1RowStride>(
51	            dstPtr, src0Ptr, src1Ptr, validRows, validCols);
52	    }
53	    return;
54	}
55	
56	template <typename T, typename TileDataDst, typename TileDataSrc0, typename TileDataSrc1>
57	PTO_INTERNAL void TAddCheck(const TileDataDst& dst, const TileDataSrc0& src0, const TileDataSrc1& src1)
58	{
59	    static_assert(
60	        std::is_same<T, typename TileDataSrc0::DType>::value && std::is_same<T, typename TileDataSrc1::DType>::value,
61	        "Fix: TADD the data type of dst must be consistent with of src0 and src1.");
62	    static_assert(
63	        std::is_same<T, int32_t>::value || std::is_same<T, int>::value || std::is_same<T, int16_t>::value ||
64	            std::is_same<T, half>::value || std::is_same<T, float16_t>::value || std::is_same<T, float>::value ||
65	            std::is_same<T, float32_t>::value,
66	        "Fix: TADD has invalid data type.");
67	    static_assert(
68	        TileDataDst::isRowMajor && TileDataSrc0::isRowMajor && TileDataSrc1::isRowMajor,
69	        "Fix: TADD only support row major layout.");
70	    unsigned validRows = dst.GetValidRow();
71	    unsigned validCols = dst.GetValidCol();
72	    PTO_ASSERT(
73	        src0.GetValidRow() == validRows && src0.GetValidCol() == validCols,
74	        "Fix: TADD input tile src0 valid shape mismatch with output tile dst shape.");
75	    PTO_ASSERT(
76	        src1.GetValidRow() == validRows && src1.GetValidCol() == validCols,
77	        "Fix: TADD input tile src1 valid shape mismatch with output tile dst shape.");
78	}
79	
80	template <typename TileDataDst, typename TileDataSrc0, typename TileDataSrc1>
81	PTO_INTERNAL void TADD_IMPL(TileDataDst& dst, TileDataSrc0& src0, TileDataSrc1& src1)
82	{
83	    using T = typename TileDataDst::DType;
84	    TAddCheck<T, TileDataDst, TileDataSrc0, TileDataSrc1>(dst, src0, src1);
85	    constexpr unsigned blockSizeElem = BLOCK_BYTE_SIZE / sizeof(T);
86	    constexpr unsigned elementsPerRepeat = REPEAT_BYTE / sizeof(T);
87	
88	    constexpr unsigned dstRowStride = TileDataDst::RowStride;
89	    constexpr unsigned src0RowStride = TileDataSrc0::RowStride;
90	    constexpr unsigned src1RowStride = TileDataSrc1::RowStride;
91	    TAdd<
92	        TileDataDst, TileDataSrc0, TileDataSrc1, elementsPerRepeat, blockSizeElem, dstRowStride, src0RowStride,
93	        src1RowStride>(dst.data(), src0.data(), src1.data(), dst.GetValidRow(), dst.GetValidCol());
94	}
